TESTS = [('rbbm_soft_reset', 121, {'soft_reset_cp': 1, 'soft_reset_re': 1, 'soft_reset_pp': 1, 'soft_reset_e2': 1, 'soft_reset_rb': 1, 'soft_reset_geometry': 0}), ('crtc_offset_cntl', 1179648, {'crtc_tile_en': 0, 'crtc_offset_flip_cntl': 0, 'crtc_stereo_offset_en': 1, 'stereo_aux': 1}), ('unnamed_0294', 12288, {'stereo_sel': 3, 'mode_nibble': 0}), ('gb_tile_config', 23, {'enable': 1, 'pipe_count': 3, 'tile_size': 1}), ('PM4_TYPE0_HDR', 66940, {'type': 0, 'count': 1, 'reg_index': 1404}), ('PM4_TYPE3_HDR', 3221298688, {'type': 3, 'count': 1, 'opcode': 30}), ('PM4_TYPE3_HDR', 3221592832, {'type': 3, 'count': 5, 'opcode': 155}), ('PM4_TYPE3_HDR', 4294774784, {'type': 3, 'count': 16381, 'opcode': 16})]


def decode(name, value):
    """Field name -> value for a register or word."""
    return {f: (value >> lo) & ((1 << (hi - lo + 1)) - 1) for f, (hi, lo) in FIELDS[name].items()}


def encode(name, **fields):
    v = 0
    for f, x in fields.items():
        hi, lo = FIELDS[name][f]
        if x >> (hi - lo + 1):
            raise ValueError('%s.%s: %d does not fit' % (name, f, x))
        v |= x << lo
    return v


def describe(name, value):
    """decode, with enum labels where the field has an enum."""
    out = {}
    for f, x in decode(name, value).items():
        e = ENUMS.get(FIELD_ENUM.get('%s.%s' % (name, f)))
        out[f] = e.get(x, x) if e else x
    return out


def selftest():
    for name, value, expect in TESTS:
        got = decode(name, value)
        for f, want in expect.items():
            assert got[f] == want, (name, hex(value), f, got[f], want)
    return len(TESTS)


if __name__ == '__main__':
    print('%s: %d vectors ok' % (UNIT, selftest()))
